import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.plugins.contentnegotiation.*
import io.ktor.serialization.kotlinx.json.*

fun Application.module(container: AppContainer) {
    install(ContentNegotiation) { json() }

    routing {
        get("/users") {
            val users = container.userService.listUsers()
            call.respond(users)
        }
    }
}

fun main() {
    val container = AppContainer() // Composition root

    embeddedServer(Netty, port = 8080) {
        module(container)
    }.start(wait = true)
}
```

Ключевой момент: `Application.module` **не создаёт

Dependency injection (DI) — передача зависимостей объекту извне вместо их создания внутри.

```kotlin
// Плохо: класс сам создаёт зависимость
class LoginViewModel {
    private val api = ApiClient()
}

// Хорошо: зависимость передаётся через конструктор
class LoginViewModel(private val api: ApiClient)

// Внедрение вручную
val vm = LoginViewModel(ApiClient())
```

Плюсы: тестируемость (легко подменить на mock), слабая связанность, переиспользование.

