class LoginViewModel @Inject constructor(
    private val api: Api,
) : ViewModel()

@Module
@InstallIn(SingletonComponent::class)
object AppModule {
    @Provides @Singleton
    fun provideApi(): Api = ApiImpl()
}
```

```kotlin
// Контракт
interface Analytics { fun log(event: String) }
class FirebaseAnalytics : Analytics {
    override fun log(event: String) = println("log: $event")
}

// Ручной DI через фабрику
