                ?: return@get call.respond(HttpStatusCode.BadRequest)

```kotlin
// Интерфейс
interface Analytics {
    fun log(event: String)
}

// Реализация
class FirebaseAnalytics : Analytics {
    override fun log(event: String) = println("log: $event")
}

// Ручной DI через конструктор
class LoginViewModel(private val analytics: Analytics) {
    fun onLogin() = analytics.log("login")
}

// Сборка графа
