В Android то же самое, но граф собирается в `Application` или фабрике ViewModel:

```kotlin
class App : Application() {
    val analytics: Analytics by lazy { FirebaseAnalytics() }
    val loginVmFactory = viewModelFactory {
        initializer { LoginViewModel(analytics) }
    }
}
```

```kotlin
// Контракт
interface AnalyticsRepository {
    fun track(event: String)
}

// Реализация
class FirebaseAnalyticsRepository : AnalyticsRepository {
    override fun track(event: String) { /* ... */ }
}

// Ручной DI: фабрика/контейнер
object AppContainer {
    val analyticsRepository: AnalyticsRepository by lazy { FirebaseAnalyticsRepository() }
}

// Потребитель
class HomeViewModel(
    private val analytics: AnalyticsRepository = AppContainer.analyticsRepository
) {
    fun onClick() = analytics.track("click")
