import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*

fun main() {
    // DI-контейнер вручную: собираем граф объектов
    val repository: UserRepository = InMemoryUserRepository()
    val service = UserService(repository)

    embeddedServer(Netty, port = 8080) {
        module(service)
    }.start(wait = true)
}

fun Application.module(service: UserService) {
    routing {
        get("/greet/{id}") {
            val id = call.parameters["id"]?.toIntOrNull() ?: 0
            call.respondText(service.greet(id))
        }
    }
}
```

Здесь `UserService` — это зависимость модуля, переданная снаружи. Роут её только использует, но не создаёт.

---

